export function useMenuItemsByCategory(categoryId: string): UseQueryResult<MenuItemDto[], Error> {
  return useQuery<MenuItemDto[], Error>({
    queryKey: ['menuItems', categoryId],
    queryFn: () => getMenuItemsByCategoryId(categoryId),
    enabled: !!categoryId,
  });
}

